class Solution {
  public int kConcatenationMaxSum(int[] arr, int k) {
    long total = 0;
    for (int x : arr) total += x;
    // the best subarray spans at most two copies, plus every full copy in between when a copy sums positive
    long best = kadane(arr, k == 1 ? 1 : 2);
    if (k > 2 && total > 0) best += total * (k - 2L);
    return (int) (best % 1_000_000_007L);
  }

  // maximum subarray sum (empty allowed) over `copies` back-to-back copies of a
  private long kadane(int[] a, int copies) {
    long cur = 0, best = 0;
    for (int c = 0; c < copies; c++) {
      for (int x : a) {
        cur = Math.max(0, cur + x);
        best = Math.max(best, cur);
      }
    }
    return best;
  }
}
